import { getEnv } from "./utils";
export let BASE_URL = getEnv("SPRINTER_URL", "https://api.sprinter.buildwithsygma.com/");
export function setBaseUrl(url) {
    BASE_URL = url;
}
export async function getSupportedChains({ baseUrl, signal, } = {}) {
    const url = new URL("/networks", baseUrl || BASE_URL);
    const response = await fetch(url, { signal }).then((response) => response.json());
    return response.data;
}
export async function getChainTokens(chainID, { baseUrl, signal } = {}) {
    const url = new URL(`/networks/${chainID}/assets/fungible`, baseUrl || BASE_URL);
    const response = await fetch(url, { signal }).then((response) => response.json());
    return response.data;
}
export async function getFungibleTokens({ baseUrl, signal, } = {}) {
    const url = new URL("/assets/fungible", baseUrl || BASE_URL);
    const response = await fetch(url, { signal }).then((response) => response.json());
    return response.data;
}
export async function getFungibleToken(token, { baseUrl, signal } = {}) {
    const url = new URL(`/assets/fungible/${token}`, baseUrl || BASE_URL);
    return await fetch(url, { signal }).then((response) => response.json());
}
export async function getUserFungibleTokens(address, token, { baseUrl, signal } = {}) {
    const url = new URL(`/accounts/${address}/assets/fungible/${token}`, baseUrl || BASE_URL);
    const response = await fetch(url, { signal }).then((response) => response.json());
    return response.data;
}
export async function getUserNativeTokens(address, { baseUrl, signal } = {}) {
    const url = new URL(`/accounts/${address}/assets/native`, baseUrl || BASE_URL);
    const response = await fetch(url, { signal }).then((response) => response.json());
    return response.data;
}
export async function getSolution({ account, destinationChain, token, amount, threshold, whitelistedSourceChains, }, { baseUrl, signal } = {}) {
    const url = new URL("/solutions/aggregation", baseUrl || BASE_URL);
    url.searchParams.set("account", account);
    url.searchParams.set("destination", String(destinationChain));
    url.searchParams.set("token", token);
    url.searchParams.set("amount", String(amount));
    //
    if (threshold)
        url.searchParams.set("threshold", String(threshold));
    if (whitelistedSourceChains?.length)
        url.searchParams.set("whitelistedSourceChains", whitelistedSourceChains.join(","));
    const response = await fetch(url, { signal }).then((response) => response.json());
    if ("error" in response)
        return response;
    return response.data;
}
export async function getContractSolution({ account, destinationChain, token, amount, contractCall, threshold, whitelistedSourceChains, }, { baseUrl, signal } = {}) {
    const url = new URL("/solutions/aggregation", baseUrl || BASE_URL);
    const response = await fetch(url, {
        signal,
        method: "POST",
        body: JSON.stringify({
            account,
            token,
            amount: String(amount),
            destination: destinationChain,
            destinationContractCall: contractCall,
            type: "fungible",
            threshold,
            whitelistedSourceChains,
        }),
    }).then((response) => response.json());
    if ("error" in response)
        return response;
    return response.data;
}
export async function getContractCallSolution({ account, destinationChain, token, amount, contractCall, threshold, whitelistedSourceChains, }, { baseUrl, signal } = {}) {
    const url = new URL("/solution/call", baseUrl || BASE_URL);
    const response = await fetch(url, {
        signal,
        method: "POST",
        body: JSON.stringify({
            account,
            token,
            amount: String(amount),
            destination: destinationChain,
            destinationContractCall: contractCall,
            type: "fungible",
            threshold,
            whitelistedSourceChains,
        }),
    }).then((response) => response.json());
    if ("error" in response)
        return response;
    return response.data;
}
